 void LetterFoundation(Node3D root,double x,double z,double floor,float halfX,float halfZ){Box(root,new(0,-.18f,0),new(halfX*2,.36f,halfZ*2),Wood,true).MaterialOverride=Textured(Wood,0,.45f);for(int a=-1;a<=1;a++)for(int b=-1;b<=1;b++){float px=a*(halfX-.3f),pz=b*(halfZ-.3f),h=Math.Max(.4f,(float)(floor-game.World.Height(x+px,z+pz)));Box(root,new(px,-h/2,pz),new(.7f,h,.7f),new(.35f,.34f,.30f),true).MaterialOverride=Textured(new(.35f,.34f,.30f),1,.5f);}}
 void LetterRamp(Node3D root,double x,double z,double floor,float start,float end){float y=(float)(game.World.Height(x,z+end)-floor);Vector3 a=new(-1.5f,0,start),b=new(1.5f,0,start),c=new(1.5f,y,end),d=new(-1.5f,y,end);var st=new SurfaceTool();st.Begin(Mesh.PrimitiveType.Triangles);foreach(var p in new[]{a,b,c,a,c,d})st.AddVertex(p);st.GenerateNormals();root.AddChild(new MeshInstance3D{Mesh=st.Commit(),MaterialOverride=Textured(new(.40f,.36f,.27f),0,.5f)});PhysicsObstacle(root,new ConvexPolygonShape3D{Points=new[]{a,b,c,d,a+Vector3.Down*.18f,b+Vector3.Down*.18f,c+Vector3.Down*.18f,d+Vector3.Down*.18f}},Vector3.Zero);}
 void LetterStone(Node3D n,Vector3 p,Vector3 size,bool solid=true)=>Box(n,p,size,new(.44f,.44f,.38f),solid).MaterialOverride=Textured(new(.44f,.44f,.38f),1,.5f);
 void LetterGable(Node3D root,float half,float eave,float peak,float z,Material mat){var st=new SurfaceTool();st.Begin(Mesh.PrimitiveType.Triangles);foreach(var p in new[]{new Vector3(-half,eave,z),new Vector3(0,peak,z),new Vector3(half,eave,z)})st.AddVertex(p);st.GenerateNormals();root.AddChild(new MeshInstance3D{Mesh=st.Commit(),MaterialOverride=mat});}
