  for(int i=0;i<3;i++){LetterCandle(n,new(-4.7f,.1f,7+i*.4f));LetterStone(n,new(-8,.5f,-3+i*4),new(.6f,1,.2f));}for(int i=0;i<4;i++){var debris=Box(n,new(4.5f,.08f,-9+i*.5f),new(.15f,.12f,1.5f),Wood);debris.RotationDegrees=new(0,i*27,0);}n.AddChild(new OmniLight3D{Position=new(0,3,0),LightEnergy=.45f,LightColor=new(.63f,.73f,.76f),OmniRange=13});
