 void LetterChurchWindow(Node3D n,float x,float y,float z,int side){var frame=new Node3D{Position=new(x,y,z),Rotation=new(0,side*Mathf.Pi/2,0)};n.AddChild(frame);Box(frame,Vector3.Zero,new(1.6f,2.8f,.06f),new(.11f,.17f,.17f));for(int i=0;i<6;i++)Box(frame,new((i%2-.5f)*.65f,(i/2-1)*.7f,.045f),new(.55f,.6f,.04f),i%3==0?new Color(.34f,.39f,.40f):i%3==1?new Color(.43f,.32f,.20f):new Color(.25f,.34f,.28f));for(int i=-1;i<=1;i++)Box(frame,new(i*.76f,0,.09f),new(.06f,2.9f,.1f),Wood);Ellipsoid(frame,new(0,1.38f,0),new(.83f,.48f,.04f),new(.24f,.31f,.29f));Tube(frame,new(-.8f,1.4f,.08f),new(0,1.9f,.08f),.06f,Wood);Tube(frame,new(.8f,1.4f,.08f),new(0,1.9f,.08f),.06f,Wood);}
 void LetterCandle(Node3D n,Vector3 p){Tube(n,p,p+Vector3.Up*.28f,.045f,new(.67f,.62f,.47f));Ellipsoid(n,p+Vector3.Up*.31f,new(.025f,.06f,.025f),new(.91f,.65f,.25f));n.AddChild(new OmniLight3D{Position=p+Vector3.Up*.4f,LightEnergy=.25f,LightColor=new(1,.70f,.38f),OmniRange=4,DistanceFadeEnabled=true,DistanceFadeBegin=45,DistanceFadeLength=15});}
 Node3D LetterPerson(Node3D parent,string name,Vector3 p,bool woman,Color coat){var root=new Node3D{Name=name,Position=p};parent.AddChild(root);HumanCharacter(root,1,0,true);var torso=root.GetNode<Node3D>("Torso");Bevel(torso,new(0,.02f,-.23f),new(.35f,.52f,.06f),coat);Bevel(torso,new(.13f,.10f,-.27f),new(.08f,.06f,.02f),woman?new Color(.60f,.44f,.28f):new Color(.47f,.46f,.37f));if(woman){var head=torso.GetNode<Node3D>("Head");Ellipsoid(head,new(0,.03f,.09f),new(.17f,.23f,.14f),new(.22f,.16f,.13f));Ellipsoid(head,new(0,.19f,-.02f),new(.16f,.065f,.14f),new(.22f,.16f,.13f));}PoseFigure(root,0,0,false);return root;}
