 void DrawLastLetter(double dt){EnsureLetterUi();if(!LetterEnabled){letterLayer.Visible=false;return;}bool church=dungeon==null&&Distance(player.Position,Ground(LetterChurchX,ExpeditionLastLetter.ChurchZ))<50,home=dungeon==null&&Distance(player.Position,Ground(LetterHomeX,ExpeditionLastLetter.HomeZ))<50;letterLayer.Visible=!paused&&dungeon==null;
  letterCaption.Text=(church||home)&&LastLetter.LineTime>0?LastLetter.Line:"";letterObjective.Text=LastLetter.Stage==1?$"THE DOOR I CLOSED / Deliver Daniel's letter to Samuel / {Distance(player.Position,Ground(LetterHomeX,ExpeditionLastLetter.HomeZ)):0}m / M map":"";
  if(LetterNodeLive(letterChurch)){letterBrotherBody.Visible=LastLetter.Stage>=3;letterChurch.GetNode<Node3D>("ReturnedLetter").Visible=LastLetter.Stage>=3;}
  if(LetterNodeLive(letterHome)){letterBrother.Visible=letterWife.Visible=LastLetter.Stage<3;letterWife.GetNode<Node3D>("RightArm/Elbow/Hand/DeliveredLetter").Visible=LastLetter.Stage==2;if(LastLetter.Stage==2){foreach(string side in new[]{"Left","Right"}){letterWife.GetNode<Node3D>(side+"Arm").RotationDegrees=new(-40,0,side=="Left"?15:-15);letterWife.GetNode<Node3D>(side+"Arm/Elbow").RotationDegrees=new(-65,0,0);}}}
 }
 void EnsureLetterUi(){if(letterLayer!=null)return;letterLayer=new CanvasLayer{Layer=8};AddChild(letterLayer);var size=GetViewport().GetVisibleRect().Size;letterCaption=new Label{Position=new(180,size.Y-260),Size=new(size.X-360,100),AutowrapMode=TextServer.AutowrapMode.WordSmart,HorizontalAlignment=HorizontalAlignment.Center,MouseFilter=Control.MouseFilterEnum.Ignore};letterCaption.AddThemeFontSizeOverride("font_size",19);letterCaption.AddThemeColorOverride("font_shadow_color",Colors.Black);letterCaption.AddThemeConstantOverride("shadow_offset_x",2);letterCaption.AddThemeConstantOverride("shadow_offset_y",2);letterLayer.AddChild(letterCaption);letterObjective=new Label{Position=new(34,166),Size=new(size.X-68,40),MouseFilter=Control.MouseFilterEnum.Ignore};letterObjective.AddThemeFontSizeOverride("font_size",15);letterObjective.Modulate=new(.79f,.71f,.52f);letterLayer.AddChild(letterObjective);}
